import { auth } from "@/lib/auth";
import type { SetupStatus, Viewer } from "@/lib/chat/types";
import { getPasswordSessionFromHeaders } from "@/lib/password-auth";
import { getSetupStatus } from "@/lib/setup";

const PASSWORD_VIEWER: Viewer = {
  email: "local@eve.dev",
  id: "eve-chat-user",
  image: null,
  name: "eve user",
};

export async function getServerViewer(setupStatus?: SetupStatus): Promise<Viewer | null> {
  const status = setupStatus ?? (await getSetupStatus());

  if (!status.appReady) {
    return null;
  }

  const requestHeaders = await headers();

  if (status.authMode === "local-dev") {
    return PASSWORD_VIEWER;
  }

  if (status.authMode === "password") {
    return getPasswordSessionFromHeaders(requestHeaders) ? PASSWORD_VIEWER : null;
  }

  if (status.authMode !== "vercel") {
    return null;
  }

  try {
    const session = await auth.api.getSession({
      headers: requestHeaders,
    });

    if (!session?.user) {
      return null;
    }

    return {
      email: session.user.email,
      id: session.user.id,
      image: session.user.image ?? null,
      name: session.user.name,
    };
  } catch {
    return null;
  }
}
"},{"path":"code/eve-auth.ts","content":"import type { AuthFn } from "eve/channels/auth";
import { auth } from "@/lib/auth";
import { getPasswordSessionFromHeaders } from "@/lib/password-auth";
import { getSetupStatus } from "@/lib/setup";

export const betterAuthEveAuth: AuthFn<Request> = async (request) => {
  const setupStatus = await getSetupStatus();

  if (!setupStatus.appReady || setupStatus.authMode !== "vercel") {
    return null;
  }

  const session = await auth.api.getSession({
    headers: request.headers,
  });

  if (!session?.user) {
    return null;
  }

  return {
    attributes: {
      email: session.user.email,
      name: session.user.name,
    },
    authenticator: "better-auth",
    issuer: "better-auth",
    principalId: session.user.id,
    principalType: "user",
    subject: session.user.email,
  };
};

export const passwordEveAuth: AuthFn<Request> = async (request) => {
  const setupStatus = await getSetupStatus();

  if (
    !setupStatus.appReady ||
    setupStatus.authMode !== "password" ||
    !getPasswordSessionFromHeaders(request.headers)
  ) {
    return null;
  }

  return {
    attributes: {
      email: "local@eve.dev",
      name: "eve user",
    },
    authenticator: "password",
    issuer: "eve-chat-template",
    principalId: "eve-chat-user",
    principalType: "user",
    subject: "eve-chat-user",
  };
};
